{
  "specificationName": "thompson-sampling-in-rpc-api-only",
  "summary": "Thompson Sampling (Beta distribution variant selection) delegation from metabob-opencode to metabob-rpc-api",
  "currentState": "COMPLIANT",
  "analysis": {
    "architecturalBoundary": {
      "description": "ML selection logic belongs in rpc-api, opencode acts as client",
      "status": "ENFORCED",
      "evidence": [
        "opencode calls POST /v2/activities/templates/{id}/select",
        "rpc-api performs Beta sampling in select_variant_thompson_sampling()",
        "No Beta sampling code exists in opencode (removed, see comments)"
      ]
    },
    "dataFlow": {
      "entry": "opencode:TemplateSelector.select(templateId)",
      "steps": [
        "1. opencode loads requested template from TemplateRepository",
        "2. opencode checks if template has candidates (A/B testing eligible)",
        "3. opencode calls RpcHttpClient.selectTemplateVariant(templateId, config)",
        "4. RpcHttpClient makes POST request to /v2/activities/templates/{id}/select",
        "5. rpc-api:select_variant() endpoint receives request",
        "6. rpc-api:select_variant_thompson_sampling() executes Thompson Sampling:",
        "   a. Find all variant_ids for activity_id from Redis",
        "   b. Load metrics (alpha, beta) for each variant",
        "   c. Sample from Beta(alpha, beta) for each variant using sample_beta()",
        "   d. Select variant with highest sample",
        "   e. Increment selection count in Redis",
        "7. rpc-api returns selected variant with selection_metadata",
        "8. opencode receives response with template_id, template, selection_metadata",
        "9. opencode loads candidate template if selected (or fallback to stable)",
        "10. opencode returns SelectionResult with thompsonSampling metadata"
      ],
      "exit": "opencode:SelectionResult with selected template and metadata"
    }
  },
  "components": [
    {
      "file": "repos/metabob-opencode/packages/opencode/src/session/template-selector.ts",
      "component": "TemplateSelector.select()",
      "currentBehavior": "Delegates Thompson Sampling to RPC API via RpcHttpClient.selectTemplateVariant()",
      "desiredBehavior": "Delegates Thompson Sampling to RPC API via RpcHttpClient.selectTemplateVariant()",
      "gap": "NONE - Already compliant",
      "lineNumbers": "118-281",
      "key_observations": [
        "betaSample() function REMOVED (see line 31-37 comments)",
        "performThompsonSampling() function REMOVED (see line 284-296 comments)",
        "Calls RpcHttpClient.selectTemplateVariant() at line 165",
        "Receives selection_metadata with alpha, beta, sample, method from RPC API",
        "Handles fallback gracefully if RPC API unavailable"
      ]
    },
    {
      "file": "repos/metabob-opencode/packages/opencode/src/util/rpc-http-client.ts",
      "component": "RpcHttpClient.selectTemplateVariant()",
      "currentBehavior": "Makes POST request to /v2/activities/templates/{activityId}/select",
      "desiredBehavior": "Makes POST request to /v2/activities/templates/{activityId}/select",
      "gap": "NONE - Already compliant",
      "lineNumbers": "41-91",
      "key_observations": [
        "Sends POST to {baseUrl}/v2/activities/templates/{activityId}/select",
        "Returns TemplateSelectionResponse with template_id, template, selection_metadata",
        "selection_metadata includes: method, alpha, beta, sample, variant",
        "Timeout of 10 seconds",
        "Reads config from METABOB_RPC_API_URL environment variable"
      ]
    },
    {
      "file": "repos/metabob-rpc-api/server/routes/activity.py",
      "component": "select_variant() endpoint",
      "currentBehavior": "POST /v2/activities/templates/{activity_id}/select endpoint calls select_variant_thompson_sampling()",
      "desiredBehavior": "POST /v2/activities/templates/{activity_id}/select endpoint calls select_variant_thompson_sampling()",
      "gap": "NONE - Already compliant",
      "lineNumbers": "355-405",
      "key_observations": [
        "Endpoint at POST /v2/activities/templates/{activity_id}/select",
        "Delegates to select_variant_thompson_sampling(redis, activity_id)",
        "Returns 404 if no variants found",
        "Returns full template with selection_metadata"
      ]
    },
    {
      "file": "repos/metabob-rpc-api/server/actions/activity.py",
      "component": "select_variant_thompson_sampling()",
      "currentBehavior": "Performs Thompson Sampling: loads all variants, samples Beta(alpha, beta), selects highest",
      "desiredBehavior": "Performs Thompson Sampling: loads all variants, samples Beta(alpha, beta), selects highest",
      "gap": "NONE - Already compliant",
      "lineNumbers": "815-937",
      "key_observations": [
        "Finds all variants using Redis keys pattern: activity:template:{activity_id}-*",
        "Loads metrics (alpha, beta) from Redis for each variant",
        "Calls sample_beta(alpha, beta) for Beta distribution sampling",
        "Selects variant with max(sample)",
        "Increments total_selections count in Redis",
        "Returns full template with selection_method, thompson_sample, alpha, beta, competing_variants"
      ]
    },
    {
      "file": "repos/metabob-rpc-api/server/actions/activity.py",
      "component": "sample_beta()",
      "currentBehavior": "Uses random.betavariate(alpha, beta) for Beta distribution sampling",
      "desiredBehavior": "Uses random.betavariate(alpha, beta) for Beta distribution sampling",
      "gap": "NONE - Already compliant",
      "lineNumbers": "73-85",
      "key_observations": [
        "Uses Python's random.betavariate(alpha, beta)",
        "Returns float in [0, 1] representing expected success rate",
        "Fallback to mean (alpha / (alpha + beta)) on error"
      ]
    },
    {
      "file": "repos/metabob-rpc-api/server/db/operations/template_metrics.py",
      "component": "update_metrics_after_execution()",
      "currentBehavior": "Updates thompson_alpha and thompson_beta based on execution success/failure",
      "desiredBehavior": "Updates thompson_alpha and thompson_beta based on execution success/failure",
      "gap": "NONE - Already compliant",
      "lineNumbers": "99-214",
      "key_observations": [
        "Incremental aggregation for metrics",
        "Thompson Sampling parameters: alpha = successes + 1, beta = failures + 1 (line 180-181)",
        "Updates improvement_gradient for boredom activity detection"
      ]
    }
  ],
  "complianceStatus": {
    "overall": "COMPLIANT",
    "details": [
      {
        "requirement": "Thompson Sampling ONLY in metabob-rpc-api",
        "status": "SATISFIED",
        "evidence": "sample_beta() exists only in repos/metabob-rpc-api/server/actions/activity.py:73-85"
      },
      {
        "requirement": "metabob-opencode calls RPC API for template selection",
        "status": "SATISFIED",
        "evidence": "RpcHttpClient.selectTemplateVariant() calls POST /v2/activities/templates/{id}/select"
      },
      {
        "requirement": "No Beta sampling logic in opencode",
        "status": "SATISFIED",
        "evidence": "betaSample() and performThompsonSampling() removed from template-selector.ts (see comments at lines 31-37 and 284-296)"
      },
      {
        "requirement": "RPC API returns selection metadata",
        "status": "SATISFIED",
        "evidence": "Response includes selection_metadata with method, alpha, beta, sample fields"
      }
    ]
  },
  "keyEndpoints": {
    "rpcApi": {
      "selectionEndpoint": "POST /v2/activities/templates/{activity_id}/select",
      "requestBody": "None (activity_id in path)",
      "responseFormat": {
        "variant_id": "Selected template variant ID",
        "activity_id": "Base activity ID",
        "task_steps": "Full template definition",
        "selection_method": "thompson_sampling",
        "thompson_sample": "Sampled value from Beta distribution",
        "thompson_alpha": "Alpha parameter (successes + 1)",
        "thompson_beta": "Beta parameter (failures + 1)",
        "competing_variants": "Number of variants considered"
      }
    }
  },
  "environmentConfiguration": {
    "opencode": {
      "METABOB_RPC_API_URL": "Required - Base URL for RPC API (e.g., http://localhost:8081)",
      "METABOB_API_KEY": "Optional - API key for authentication"
    },
    "rpcApi": {
      "redis": "Required - Redis connection for metrics storage",
      "surrealdb": "Required - SurrealDB for persistent storage"
    }
  },
  "validationChecks": [
    {
      "check": "No Beta sampling code in metabob-opencode",
      "command": "grep -r 'betavariate\\|Beta.*distribution\\|sample.*beta' repos/metabob-opencode/packages/opencode/src --exclude-dir=node_modules",
      "expectedResult": "No matches (or only in comments)",
      "status": "PASS"
    },
    {
      "check": "RPC API has Thompson Sampling implementation",
      "command": "grep -A 10 'def sample_beta' repos/metabob-rpc-api/server/actions/activity.py",
      "expectedResult": "Function exists using random.betavariate",
      "status": "PASS"
    },
    {
      "check": "opencode calls RPC API for selection",
      "command": "grep -A 5 'selectTemplateVariant' repos/metabob-opencode/packages/opencode/src/util/rpc-http-client.ts",
      "expectedResult": "Function makes POST request to /v2/activities/templates/{id}/select",
      "status": "PASS"
    }
  ],
  "recommendations": [
    {
      "priority": "LOW",
      "category": "monitoring",
      "description": "Add metrics for RPC API call success/failure rates",
      "rationale": "Track fallback behavior when RPC API unavailable"
    },
    {
      "priority": "LOW",
      "category": "documentation",
      "description": "Document METABOB_RPC_API_URL configuration in deployment docs",
      "rationale": "Critical environment variable for Thompson Sampling to work"
    }
  ],
  "testScenarios": [
    {
      "scenario": "Template selection with single variant",
      "steps": [
        "1. Call TemplateSelector.select('template-with-no-candidates')",
        "2. Verify it returns immediately without calling RPC API",
        "3. Verify no Thompson Sampling metadata in result"
      ],
      "expectedOutcome": "Direct load without Thompson Sampling"
    },
    {
      "scenario": "Template selection with multiple variants (Thompson Sampling)",
      "steps": [
        "1. Call TemplateSelector.select('template-with-candidates')",
        "2. Verify RPC API call to POST /v2/activities/templates/{id}/select",
        "3. Verify response includes thompson_sample, alpha, beta",
        "4. Verify selected variant matches highest Beta sample"
      ],
      "expectedOutcome": "Thompson Sampling performed in RPC API, metadata returned"
    },
    {
      "scenario": "RPC API unavailable fallback",
      "steps": [
        "1. Stop RPC API server",
        "2. Call TemplateSelector.select('template-with-candidates')",
        "3. Verify graceful fallback to stable template",
        "4. Verify fallbackReason mentions RPC API unavailable"
      ],
      "expectedOutcome": "Graceful degradation to stable template"
    }
  ]
}
